@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@using Microsoft.AspNetCore.Components.Forms
@inject ICatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<h1 class="mb-4">Enrollment Request</h1>
<p class="text-muted mb-4">Fill out the form below to submit an enrollment request. You will receive a confirmation once processed.</p>

<div class="row">
    <div class="col-md-8 col-lg-6">
        <EditForm Model="model" method="post" OnValidSubmit="HandleSubmit" FormName="enrollment" Enhance>
            <DataAnnotationsValidator />
            <AntiforgeryToken />

            <div class="mb-3">
                <label for="studentName" class="form-label">Full Name</label>
                <InputText id="studentName" @bind-Value="model.StudentName" class="form-control" />
                <ValidationMessage For="() => model.StudentName" />
            </div>

            <div class="mb-3">
                <label for="studentId" class="form-label">Student ID</label>
                <InputText id="studentId" @bind-Value="model.StudentId" class="form-control" />
                <ValidationMessage For="() => model.StudentId" />
            </div>

            <div class="mb-3">
                <label for="courseId" class="form-label">Course</label>
                <InputSelect id="courseId" @bind-Value="model.CourseId" class="form-select">
                    <option value="0">— Select a course —</option>
                    @foreach (var course in courses)
                    {
                        <option value="@course.Id">@course.Code — @course.Title</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => model.CourseId" />
            </div>

            <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
        </EditForm>
    </div>
</div>

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest model { get; set; } = new();

    [SupplyParameterFromQuery]
    private int? CourseId { get; set; }

    private IReadOnlyList<Course> courses = [];

    protected override void OnInitialized()
    {
        courses = CatalogService.GetCourses();

        if (CourseId.HasValue && model.CourseId == 0)
        {
            model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        var selectedCourse = CatalogService.GetCourseById(model.CourseId);
        NavigationManager.NavigateTo(
            $"enroll/confirmation?name={Uri.EscapeDataString(model.StudentName)}&courseCode={Uri.EscapeDataString(selectedCourse?.Code ?? "")}&courseTitle={Uri.EscapeDataString(selectedCourse?.Title ?? "")}");
    }

    [Inject]
    private NavigationManager NavigationManager { get; set; } = default!;
}

